package cl.bolsillo.app;

import org.json.*;
import java.time.*;
import java.util.*;

/** Pure accounting rules. Amounts are integer Chilean pesos. */
public final class Ledger {
 public static final long MAX=1000000000000L;
 static String today(){return LocalDate.now(ZoneId.of("America/Santiago")).toString();}
 static String id(){return UUID.randomUUID().toString();}
 static JSONObject account(String id,String name,String type,String institution)throws Exception{return new JSONObject().put("id",id).put("name",name).put("type",type).put("institution",institution).put("opening",0).put("included",true).put("archived",false).put("limit",0).put("closingDay",1).put("dueDay",5).put("color","#087F79").put("yield",new JSONObject().put("enabled",false).put("annualRate",0).put("basis","365").put("compound",true).put("withholding",0).put("startDate","").put("creditFrequency","monthly"));}
 static JSONObject initial()throws Exception{
  JSONObject d=new JSONObject();for(String key:new String[]{"accounts","categories","transactions","groups","budgets","goals","recurring","templates","people","planned","receivables","changeLog"})d.put(key,new JSONArray());
  d.getJSONArray("accounts").put(account("bank-bancoestado","BancoEstado","bank","bancoestado")).put(account("bank-mach","MACHBANK","bank","mach")).put(account("mach-savings","MACHBANK · Ahorro","savings","mach")).put(account("cash","Efectivo","cash","other"));
  String[] cats={"Alimentación","Transporte","Hogar","Salud","Compras","Ocio","Educación","Suscripciones","Otros gastos","Trabajo","Ventas","Regalos","Otros ingresos","Rendimientos de ahorro"};
  for(int i=0;i<cats.length;i++)d.getJSONArray("categories").put(new JSONObject().put("id",i<9?"expense-"+i:i==13?"income-yield":"income-"+(i-9)).put("name",cats[i]).put("type",i<9?"expense":"income").put("emoji","").put("color","#087F79").put("archived",false));return d;
 }
 static JSONObject find(JSONArray a,String id)throws Exception{for(int i=0;i<a.length();i++)if(id.equals(a.getJSONObject(i).optString("id")))return a.getJSONObject(i);return null;}
 static Map<String,Long> balances(JSONObject d,String asOf)throws Exception{
  Map<String,Long> result=new LinkedHashMap<>();Map<String,JSONObject> accountById=new HashMap<>();JSONArray accounts=d.getJSONArray("accounts"),txs=d.getJSONArray("transactions");for(int i=0;i<accounts.length();i++){JSONObject a=accounts.getJSONObject(i);result.put(a.getString("id"),a.getLong("opening"));accountById.put(a.getString("id"),a);}
  for(int i=0;i<txs.length();i++){JSONObject t=txs.getJSONObject(i);if(!"posted".equals(t.optString("status")))continue;String from=t.getString("account"),type=t.getString("type");JSONObject a=accountById.get(from);if(t.getString("date").compareTo(asOf)>0&&!("credit".equals(a.optString("type"))&&t.optInt("installments",1)>1))continue;long amount=t.getLong("amount");result.put(from,Math.addExact(result.get(from),(type.equals("income")||type.equals("repayment"))?amount:-amount));if(type.equals("transfer"))result.put(t.getString("to"),Math.addExact(result.get(t.getString("to")),amount));}return result;
 }
 static long flow(JSONObject d,String month,String type,String category)throws Exception{String asOf=today();long sum=0;JSONArray ts=d.getJSONArray("transactions");for(int i=0;i<ts.length();i++){JSONObject t=ts.getJSONObject(i);if(t.optString("status").equals("posted")&&!t.optBoolean("excluded")&&t.optString("type").equals(type)&&t.optString("date").startsWith(month)&&t.optString("date").compareTo(asOf)<=0&&(category.isEmpty()||category.equals(t.optString("category"))))sum=Math.addExact(sum,type.equals("expense")?Finance.personalExpense(t):t.getLong("amount"));}return sum;}
 /** One pass over movements, rather than recomputing every account for each chart day. */
 static long[] dailyTotals(JSONObject d,LocalDate first,int days)throws Exception{
  long[] result=new long[days],delta=new long[days];if(days==0)return result;Map<String,JSONObject> included=new HashMap<>(),byId=new HashMap<>();JSONArray accounts=d.getJSONArray("accounts");Map<String,Long> opening=balances(d,first.toString());long total=0;for(int i=0;i<accounts.length();i++){JSONObject account=accounts.getJSONObject(i);byId.put(account.getString("id"),account);if(account.optBoolean("included")){included.put(account.getString("id"),account);total+=opening.get(account.getString("id"));}}String start=first.toString(),end=first.plusDays(days-1).toString();JSONArray movements=d.getJSONArray("transactions");for(int i=0;i<movements.length();i++){JSONObject tx=movements.getJSONObject(i);String date=tx.optString("date");if(!tx.optString("status").equals("posted")||date.compareTo(start)<=0||date.compareTo(end)>0)continue;JSONObject origin=byId.get(tx.optString("account"));if(origin!=null&&origin.optString("type").equals("credit")&&tx.optInt("installments",1)>1)continue;int day=(int)java.time.temporal.ChronoUnit.DAYS.between(first,LocalDate.parse(date));String type=tx.optString("type");long amount=tx.getLong("amount");if(included.containsKey(tx.optString("account")))delta[day]+=(type.equals("income")||type.equals("repayment"))?amount:-amount;if(type.equals("transfer")&&included.containsKey(tx.optString("to")))delta[day]+=amount;}
  for(int i=0;i<days;i++){total+=delta[i];result[i]=total;}return result;
 }
 static void require(boolean b,String message)throws Exception{if(!b)throw new Exception(message);}
 static long money(JSONObject o,String key,boolean signed)throws Exception{Object v=o.get(key);require(v instanceof Number,"Monto inválido: "+key);double n=((Number)v).doubleValue();require(Double.isFinite(n)&&n==Math.rint(n)&&n<=MAX&&n>=(signed?-MAX:0),"Monto fuera de rango: "+key);return ((Number)v).longValue();}
 static void validate(JSONObject d)throws Exception{
  Finance.migrate(d);Finance.validate(d);
  JSONArray changes=d.optJSONArray("changeLog");require(changes!=null&&changes.length()<=100000,"Historial de cambios inválido");
  String[] keys={"accounts","categories","transactions","groups","budgets","goals","recurring","templates"};int[] limits={100,300,20000,100,300,100,300,100};
  for(int n=0;n<keys.length;n++){JSONArray a=d.getJSONArray(keys[n]);require(a.length()<=limits[n],"Demasiados registros en "+keys[n]);Set<String> ids=new HashSet<>();for(int i=0;i<a.length();i++){String id=a.getJSONObject(i).getString("id");require(!id.isEmpty()&&id.length()<=160&&ids.add(id),"Identificador inválido o repetido");}}
  JSONArray accounts=d.getJSONArray("accounts"),categories=d.getJSONArray("categories");require(accounts.length()>0,"Debe existir al menos una cuenta");
  for(int i=0;i<accounts.length();i++){JSONObject a=accounts.getJSONObject(i);require(!a.getString("name").trim().isEmpty(),"La cuenta necesita nombre");require(Arrays.asList("cash","bank","credit","savings","investment").contains(a.getString("type")),"Tipo de cuenta inválido");money(a,"opening",true);money(a,"limit",false);}
  for(int i=0;i<categories.length();i++){JSONObject c=categories.getJSONObject(i);require(!c.getString("name").trim().isEmpty()&&Arrays.asList("income","expense").contains(c.getString("type")),"Categoría inválida");}
  for(String key:new String[]{"transactions","recurring","templates"}){JSONArray a=d.getJSONArray(key);for(int i=0;i<a.length();i++){JSONObject t=a.getJSONObject(i);require(money(t,"amount",false)>0,"El monto debe ser mayor que cero");require(find(accounts,t.getString("account"))!=null,"Cuenta inexistente");String type=t.getString("type");require(Arrays.asList("expense","income","transfer","repayment","loan").contains(type),"Tipo inválido");if(type.equals("transfer"))require(!t.getString("account").equals(t.optString("to"))&&find(accounts,t.optString("to"))!=null,"Destino inválido");else if(!type.equals("repayment")&&!type.equals("loan")){JSONObject cat=find(categories,t.optString("category"));require(cat!=null&&type.equals(cat.optString("type")),"Categoría incompatible");}if(key.equals("transactions")){LocalDate.parse(t.getString("date"));require(Arrays.asList("posted","pending").contains(t.getString("status")),"Estado inválido");int count=t.optInt("installments",1);require(count>=1&&count<=120,"Cuotas inválidas");JSONArray shares=t.optJSONArray("shares");long total=0;if(shares!=null)for(int j=0;j<shares.length();j++){JSONObject s=shares.getJSONObject(j);require(money(s,"amount",false)>0,"Parte inválida");total+=s.getLong("amount");}require(total<=t.getLong("amount")&&(total==0||(type.equals("expense")||type.equals("loan"))&&count==1),"Gasto compartido inválido");}if(type.equals("loan")||key.equals("recurring"))Finance.validateShares(d,t,type.equals("loan"));if(key.equals("recurring")){LocalDate.parse(t.getString("next"));require(Arrays.asList("weekly","monthly","yearly").contains(t.getString("frequency")),"Frecuencia inválida");}}}
  Map<String,Long> claims=new HashMap<>(),paid=new HashMap<>();JSONArray prior=d.getJSONArray("receivables");for(int i=0;i<prior.length();i++){JSONObject p=prior.getJSONObject(i);String key="prior:"+p.getString("id");claims.put(key,p.getLong("amount"));paid.put(key,p.getLong("settled"));}JSONArray txs=d.getJSONArray("transactions");for(int i=0;i<txs.length();i++){JSONObject t=txs.getJSONObject(i);if((t.optString("type").equals("expense")||t.optString("type").equals("loan"))&&t.optString("status").equals("posted")){JSONArray shares=t.optJSONArray("shares");if(shares!=null)for(int j=0;j<shares.length();j++){JSONObject s=shares.getJSONObject(j);String k=t.getString("id")+":"+s.getString("id");require(!claims.containsKey(k),"Parte repetida");claims.put(k,s.getLong("amount"));}}}
  for(int i=0;i<txs.length();i++){JSONObject t=txs.getJSONObject(i);if(t.optString("type").equals("repayment")){String k=t.getString("receivable");require(claims.containsKey(k),"Cobro sin gasto compartido");paid.put(k,paid.getOrDefault(k,0L)+t.getLong("amount"));require(paid.get(k)<=claims.get(k),"El cobro supera la deuda");}}
  Set<String> budgetCats=new HashSet<>();JSONArray budgets=d.getJSONArray("budgets");for(int i=0;i<budgets.length();i++){JSONObject b=budgets.getJSONObject(i),c=find(categories,b.getString("category"));require(c!=null&&c.optString("type").equals("expense")&&budgetCats.add(c.getString("id"))&&money(b,"amount",false)>0,"Presupuesto inválido o repetido");}
  for(String k:new String[]{"goals","groups"}){JSONArray a=d.getJSONArray(k);for(int i=0;i<a.length();i++){JSONObject g=a.getJSONObject(i);JSONArray ids=g.getJSONArray("accounts");Set<String> unique=new HashSet<>();for(int j=0;j<ids.length();j++)require(find(accounts,ids.getString(j))!=null&&unique.add(ids.getString(j)),"Cuenta de grupo/meta inválida");if(k.equals("goals")){require(money(g,"target",false)>0,"Meta inválida");if(!g.optString("deadline").isEmpty())LocalDate.parse(g.getString("deadline"));}}}
  balances(d,today());
 }
 static String next(String date,String frequency,int anchor){LocalDate n=LocalDate.parse(date);if(frequency.equals("weekly"))return n.plusWeeks(1).toString();n=n.withDayOfMonth(1).plusMonths(frequency.equals("yearly")?12:1);return n.withDayOfMonth(Math.min(anchor==0?LocalDate.parse(date).getDayOfMonth():anchor,n.lengthOfMonth())).toString();}
 static void automatic(JSONObject d)throws Exception{JSONArray rules=d.getJSONArray("recurring"),txs=d.getJSONArray("transactions");for(int i=0;i<rules.length();i++){JSONObject r=rules.getJSONObject(i);int anchor=r.optInt("anchorDay",0);if(anchor==0){anchor=LocalDate.parse(r.getString("next")).getDayOfMonth();r.put("anchorDay",anchor);}int count=0;while(r.optBoolean("active")&&r.optBoolean("automatic")&&r.getString("next").compareTo(today())<=0&&count++<120&&txs.length()<19900){String id="auto-"+r.getString("id")+"-"+r.getString("next");if(find(txs,id)==null){JSONObject t=NativeSync.transaction(r.getString("type"),r.getLong("amount"),r.getString("account"),r.optString("to"),r.optString("category"),r.getString("name"),"manual","");t.put("id",id).put("date",r.getString("next")).put("tags","recurrente").put("shares",r.optJSONArray("shares")==null?new JSONArray():r.getJSONArray("shares"));txs.put(t);}r.put("next",next(r.getString("next"),r.getString("frequency"),anchor));}}}
}

